
const movieForm = document.getElementById("movieForm");
const moviesList = document.getElementById("moviesList");
const message = document.getElementById("message");
const submitBtn = document.getElementById("submitBtn");
const cancelBtn = document.getElementById("cancelBtn");

async function loadMovies() {
    try {
        const response = await fetch("/api/movies");
        const movies = await response.json();

        if (!response.ok) throw new Error(movies.error);

        moviesList.innerHTML = "";

        if (movies.length === 0) {
            moviesList.innerHTML =
                '<tr><td colspan="5">No movies found. Add your first movie!</td></tr>';
            return;
        }

        movies.forEach(movie => {
            const row = document.createElement("tr");

            const values = [
                movie.title,
                movie.director,
                movie.year,
                movie.genre
            ];

            values.forEach(value => {
                const cell = document.createElement("td");
                cell.textContent = value;
                row.appendChild(cell);
            });

            const actions = document.createElement("td");

            const editButton = document.createElement("button");
            editButton.textContent = "Edit";
            editButton.className = "edit-btn";
            editButton.addEventListener("click", () => editMovie(movie));

            const deleteButton = document.createElement("button");
            deleteButton.textContent = "Delete";
            deleteButton.className = "delete-btn";
            deleteButton.addEventListener("click", () => deleteMovie(movie._id));

            actions.append(editButton, deleteButton);
            row.appendChild(actions);
            moviesList.appendChild(row);
        });
    } catch (error) {
        message.textContent = "Error loading movies: " + error.message;
    }
}

movieForm.addEventListener("submit", async event => {
    event.preventDefault();

    const id = document.getElementById("movieId").value;

    const movie = {
        title: document.getElementById("title").value.trim(),
        director: document.getElementById("director").value.trim(),
        year: Number(document.getElementById("year").value),
        genre: document.getElementById("genre").value.trim()
    };

    try {
        const response = await fetch(
            id ? `/api/movies/${id}` : "/api/movies",
            {
                method: id ? "PUT" : "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(movie)
            }
        );

        const result = await response.json();

        if (!response.ok) throw new Error(result.error);

        message.textContent = id
            ? "Movie updated successfully!"
            : "Movie added successfully!";

        resetForm();
        loadMovies();
    } catch (error) {
        message.textContent = "Error: " + error.message;
    }
});

function editMovie(movie) {
    document.getElementById("movieId").value = movie._id;
    document.getElementById("title").value = movie.title;
    document.getElementById("director").value = movie.director;
    document.getElementById("year").value = movie.year;
    document.getElementById("genre").value = movie.genre;

    submitBtn.textContent = "Update Movie";
    cancelBtn.hidden = false;

    window.scrollTo({ top: 0, behavior: "smooth" });
}

async function deleteMovie(id) {
    if (!confirm("Are you sure you want to delete this movie?")) return;

    try {
        const response = await fetch(`/api/movies/${id}`, {
            method: "DELETE"
        });

        const result = await response.json();

        if (!response.ok) throw new Error(result.error);

        message.textContent = "Movie deleted successfully!";
        loadMovies();
    } catch (error) {
        message.textContent = "Error: " + error.message;
    }
}

function resetForm() {
    movieForm.reset();
    document.getElementById("movieId").value = "";
    submitBtn.textContent = "Add Movie";
    cancelBtn.hidden = true;
}

cancelBtn.addEventListener("click", resetForm);

loadMovies();
